{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"/**
 * Deterministic reliability aggregation for the Agent Dev benefit report.
 *
 * Semantics (kept explicit so pass^k is never confused with pass@k):
 *  - A *case* is a scenario executed `k` times (trials).
 *  - A trial status is one of: 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip'.
 *  - Only 'pass' and 'fail' are *complete* trial outcomes. A case whose trials are
 *    not exactly `k` complete outcomes is `incomplete` and is excluded from the
 *    denominator of pass^k / pass@k / flake, but is always reported (never dropped).
 *  - pass^k  = complete cases where *all* k trials passed / complete cases.
 *  - pass@k  = complete cases where *at least one* trial passed / complete cases.
 *  - flake   = complete cases where the first trial failed and a later fixed rerun
 *    succeeded. The first failure is retained (a retried success never erases the
 *    original gate failure), so a flaky case never counts towards pass^k.
 *  - per-trial success rate = passing trials / recorded trials over complete cases.
 *  - Anchors: `positive` cases must pass every trial, `negative` cases must reject
 *    every trial (a 'pass' verdict for a negative anchor means the rejection
 *    succeeded). Any anchor violation is gate=fail.
 *  - Safety-critical cases must have 0 skip and 0 flake, otherwise gate=fail.
 *  - If the number of complete cases is below the registered design gate
 *    (k = 3, minCases >= 20) the gate is `insufficient-sample`; a small sample is
 *    never reported as PASS.
 *
 * The module is pure: no I/O, no clock, no network, no process effects.
 */

export const RELIABILITY_GATE = Object.freeze({
  PASS: 'pass',
  FAIL: 'fail',
  INSUFFICIENT_SAMPLE: 'insufficient-sample',
});

export const INCOMPLETE_STATUSES = Object.freeze(['missing', 'timeout', 'crash', 'skip']);
export const TRIAL_STATUSES = Object.freeze(['pass', 'fail', ...INCOMPLETE_STATUSES]);

const COMPLETE_STATUSES = new Set(['pass', 'fail']);

/** Normalize a raw trial status into the closed status vocabulary. */
export function normalizeStatus(value) {
  const raw = String(value ?? '').trim().toLowerCase();
  if (raw === 'pass' || raw === 'passed' || raw === 'ok' || raw === 'success') return 'pass';
  if (raw === 'fail' || raw === 'failed' || raw === 'error') return 'fail';
  if (INCOMPLETE_STATUSES.includes(raw)) return raw;
  return 'missing';
}

/** True when the status represents a recorded, comparable trial outcome. */
export function isCompleteStatus(status) {
  return COMPLETE_STATUSES.has(normalizeStatus(status));
}

function toPositiveInt(value, fallback) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return fallback;
  return Math.floor(numeric);
}

function toFiniteNumber(value, fallback) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return numeric;
}

/** Ratio with stable rounding; keeps an exact 0 rather than null/undefined. */
export function ratio(numerator, denominator, digits = 4) {
  const n = Number(numerator) || 0;
  const d = Number(denominator) || 0;
  if (d <= 0) return 0;
  const factor = 10 ** digits;
  return Math.round((n / d) * factor) / factor;
}

function emptyStatusCounts() {
  return { pass: 0, fail: 0, missing: 0, timeout: 0, crash: 0, skip: 0 };
}

/**
 * Evaluate one case against the registered `k`.
 * Returns a plain JSON-friendly object; caller-owned inputs are never mutated.
 */
export function evaluateCase(testCase, k) {
  const source = testCase && typeof testCase === 'object' ? testCase : {};
  const trials = Array.isArray(source.trials) ? source.trials : [];
  const statuses = trials.map((trial) => normalizeStatus(trial && typeof trial === 'object' ? trial.status ?? trial.outcome : trial));
  const statusCounts = emptyStatusCounts();
  for (const status of statuses) statusCounts[status] += 1;

  const trialCount = statuses.length;
  const incompleteReasons = [];
  for (const status of statuses) {
    if (!COMPLETE_STATUSES.has(status) && !incompleteReasons.includes(status)) incompleteReasons.push(status);
  }
  if (trialCount !== k && !incompleteReasons.includes('missing')) incompleteReasons.unshift('missing');

  const complete = trialCount === k && incompleteReasons.length === 0;
  const passes = statusCounts.pass;
  const failures = statusCounts.fail;
  const allPass = complete && passes === k;
  const anyPass = passes > 0;
  const firstTrialFailed = statuses.length > 0 && statuses[0] === 'fail';
  const firstTrialPassed = statuses.length > 0 && statuses[0] === 'pass';
  const flake = complete && firstTrialFailed && anyPass;

  return {
    id: String(source.id ?? ''),
    kind: String(source.kind ?? source.category ?? 'functional'),
    safetyCritical: source.safetyCritical === true,
    anchor: source.anchor === true,
    trials: statuses,
    trialCount,
    statusCounts,
    complete,
    incompleteReasons,
    passes,
    failures,
    allPass,
    anyPass,
    firstTrialPassed,
    firstTrialFailed,
    firstTrialFailureRetained: firstTrialFailed,
    flake,
  };
}

/**
 * Aggregate a deterministic reliability fixture.
 *
 * @param {object} fixture registered fixture (k, minCases, flakeThreshold, anchors, cases)
 * @param {object} [options] optional overrides for k / minCases / flakeThreshold
 */
export function aggregateReliability(fixture, options = {}) {
  const source = fixture && typeof fixture === 'object' ? fixture : {};
  const opts = options && typeof options === 'object' ? options : {};

  const k = toPositiveInt(source.k ?? opts.k, 1);
  const minCases = toPositiveInt(source.minCases ?? opts.minCases, 0);
  const flakeThreshold = toFiniteNumber(source.flakeThreshold ?? opts.flakeThreshold, 0);

  const rawCases = Array.isArray(source.cases) ? source.cases : [];
  const evaluated = rawCases.map((testCase) => evaluateCase(testCase, k));

  const completeCases = evaluated.filter((entry) => entry.complete);
  const incompleteCases = evaluated.filter((entry) => !entry.complete);

  const allPassCases = completeCases.filter((entry) => entry.allPass);
  const anyPassCases = completeCases.filter((entry) => entry.anyPass);
  const flakeCases = completeCases.filter((entry) => entry.flake);
  const firstFailureRetainedCases = completeCases.filter((entry) => entry.firstTrialFailureRetained);

  const recordedTrials = completeCases.reduce((sum, entry) => sum + entry.trialCount, 0);
  const passingTrials = completeCases.reduce((sum, entry) => sum + entry.passes, 0);

  const passK = ratio(allPassCases.length, completeCases.length);
  const passAtK = ratio(anyPassCases.length, completeCases.length);
  const perTrialSuccessRate = ratio(passingTrials, recordedTrials);
  const flakeRate = ratio(flakeCases.length, completeCases.length);

  const byId = new Map(evaluated.map((entry) => [entry.id, entry]));

  const anchorIds = {
    positive: Array.isArray(source.anchors?.positive) ? source.anchors.positive.map((id) => String(id)) : [],
    negative: Array.isArray(source.anchors?.negative) ? source.anchors.negative.map((id) => String(id)) : [],
  };

  const anchorSummary = {};
  const anchorViolations = [];
  for (const kind of ['positive', 'negative']) {
    const ids = anchorIds[kind];
    const details = [];
    for (const id of ids) {
      const entry = byId.get(id);
      const passed = Boolean(entry && entry.complete && entry.allPass);
      details.push({
        id,
        present: Boolean(entry),
        passed,
        reason: passed ? null : (entry ? 'anchor-violation' : 'anchor-case-missing'),
      });
      if (!passed) anchorViolations.push({ kind, id, reason: entry ? 'anchor-violation' : 'anchor-case-missing' });
    }
    anchorSummary[kind] = {
      caseIds: ids,
      expected: kind === 'positive' ? 'all trials pass' : 'all trials reject',
      passed: details.every((detail) => detail.passed),
      details,
    };
  }

  const safetyCases = evaluated.filter((entry) => entry.safetyCritical);
  const safetyViolations = [];
  for (const entry of safetyCases) {
    if (entry.statusCounts.skip > 0) safetyViolations.push({ id: entry.id, reason: 'safety-skip' });
    if (entry.flake) safetyViolations.push({ id: entry.id, reason: 'safety-flake' });
  }

  const failReasons = [];
  for (const violation of anchorViolations) failReasons.push(`${violation.reason}:${violation.kind}:${violation.id}`);
  for (const violation of safetyViolations) failReasons.push(`${violation.reason}:${violation.id}`);
  if (flakeRate > flakeThreshold) failReasons.push(`flake-rate-exceeds-threshold:${flakeRate}>${flakeThreshold}`);

  const sampleReasons = [];
  if (completeCases.length < minCases) {
    sampleReasons.push(`insufficient-sample:${completeCases.length}/${minCases}`);
  }
  if (k !== 3) sampleReasons.push(`unregistered-k:${k}`);

  let gate = RELIABILITY_GATE.PASS;
  let gateReasons = ['all-conditions-met'];
  if (failReasons.length > 0) {
    gate = RELIABILITY_GATE.FAIL;
    gateReasons = failReasons;
  } else if (sampleReasons.length > 0) {
    gate = RELIABILITY_GATE.INSUFFICIENT_SAMPLE;
    gateReasons = sampleReasons;
  }

  return {
    fixtureId: String(source.fixtureId ?? source.id ?? 'unknown-fixture'),
    fixtureKind: String(source.fixtureKind ?? 'deterministic-oracle'),
    deterministic: source.deterministic === true,
    oracle: typeof source.oracle === 'string' ? source.oracle : null,
    k,
    minCases,
    flakeThreshold,
    rawCaseCount: evaluated.length,
    completeCaseCount: completeCases.length,
    incompleteCaseCount: incompleteCases.length,
    recordedTrials,
    passingTrials,
    passK,
    passAtK,
    perTrialSuccessRate,
    flakeRate,
    flakeCaseIds: flakeCases.map((entry) => entry.id),
    firstFailureRetainedCaseIds: firstFailureRetainedCases.map((entry) => entry.id),
    allPassCaseCount: allPassCases.length,
    anyPassCaseCount: anyPassCases.length,
    incomplete: incompleteCases.map((entry) => ({
      id: entry.id,
      kind: entry.kind,
      statusCounts: entry.statusCounts,
      reasons: entry.incompleteReasons,
    })),
    anchors: anchorSummary,
    safety: {
      caseIds: safetyCases.map((entry) => entry.id),
      skipCount: safetyCases.reduce((sum, entry) => sum + entry.statusCounts.skip, 0),
      flakeCaseIds: safetyCases.filter((entry) => entry.flake).map((entry) => entry.id),
      violations: safetyViolations,
    },
    cases: evaluated,
    gate,
    gateReasons,
    sampleReasons,
  };
}

export default aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"/**
 * Type declarations for scripts/lib/reliability-aggregation.mjs
 */

export type ReliabilityTrialStatus = 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip';

export type ReliabilityGateStatus = 'pass' | 'fail' | 'insufficient-sample';

export interface ReliabilityFixtureTrial {
  status?: string;
  outcome?: string;
  [key: string]: unknown;
}

export interface ReliabilityFixtureCase {
  id?: string;
  kind?: string;
  category?: string;
  safetyCritical?: boolean;
  anchor?: boolean;
  trials?: ReliabilityFixtureTrial[];
  [key: string]: unknown;
}

export interface ReliabilityFixture {
  fixtureId?: string;
  id?: string;
  fixtureKind?: string;
  deterministic?: boolean;
  oracle?: string;
  k?: number;
  minCases?: number;
  flakeThreshold?: number;
  anchors?: { positive?: string[]; negative?: string[] };
  cases?: ReliabilityFixtureCase[];
  [key: string]: unknown;
}

export interface ReliabilityStatusCounts {
  pass: number;
  fail: number;
  missing: number;
  timeout: number;
  crash: number;
  skip: number;
}

export interface ReliabilityCaseResult {
  id: string;
  kind: string;
  safetyCritical: boolean;
  anchor: boolean;
  trials: ReliabilityTrialStatus[];
  trialCount: number;
  statusCounts: ReliabilityStatusCounts;
  complete: boolean;
  incompleteReasons: ReliabilityTrialStatus[];
  passes: number;
  failures: number;
  allPass: boolean;
  anyPass: boolean;
  firstTrialPassed: boolean;
  firstTrialFailed: boolean;
  firstTrialFailureRetained: boolean;
  flake: boolean;
}

export interface ReliabilityAnchorDetail {
  id: string;
  present: boolean;
  passed: boolean;
  reason: string | null;
}

export interface ReliabilityAnchorSummary {
  caseIds: string[];
  expected: string;
  passed: boolean;
  details: ReliabilityAnchorDetail[];
}

export interface ReliabilitySummary {
  fixtureId: string;
  fixtureKind: string;
  deterministic: boolean;
  oracle: string | null;
  k: number;
  minCases: number;
  flakeThreshold: number;
  rawCaseCount: number;
  completeCaseCount: number;
  incompleteCaseCount: number;
  recordedTrials: number;
  passingTrials: number;
  passK: number;
  passAtK: number;
  perTrialSuccessRate: number;
  flakeRate: number;
  flakeCaseIds: string[];
  firstFailureRetainedCaseIds: string[];
  allPassCaseCount: number;
  anyPassCaseCount: number;
  incomplete: Array<{ id: string; kind: string; statusCounts: ReliabilityStatusCounts; reasons: ReliabilityTrialStatus[] }>;
  anchors: { positive: ReliabilityAnchorSummary; negative: ReliabilityAnchorSummary };
  safety: {
    caseIds: string[];
    skipCount: number;
    flakeCaseIds: string[];
    violations: Array<{ id: string; reason: string }>;
  };
  cases: ReliabilityCaseResult[];
  gate: ReliabilityGateStatus;
  gateReasons: string[];
  sampleReasons: string[];
}

export declare const RELIABILITY_GATE: Readonly<{
  PASS: 'pass';
  FAIL: 'fail';
  INSUFFICIENT_SAMPLE: 'insufficient-sample';
}>;

export declare const INCOMPLETE_STATUSES: readonly ['missing', 'timeout', 'crash', 'skip'];

export declare const TRIAL_STATUSES: readonly ReliabilityTrialStatus[];

export declare function normalizeStatus(value: unknown): ReliabilityTrialStatus;

export declare function isCompleteStatus(status: unknown): boolean;

export declare function ratio(numerator: number, denominator: number, digits?: number): number;

export declare function evaluateCase(testCase: ReliabilityFixtureCase, k: number): ReliabilityCaseResult;

export declare function aggregateReliability(fixture: ReliabilityFixture, options?: { k?: number; minCases?: number; flakeThreshold?: number }): ReliabilitySummary;

