import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');
const RELIABILITY_FIXTURE_PATH = 'shared/agent-dev/reliability-fixture.json';

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@')
    ? name.replace('/', '\\')
    : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0
      ? 1
      : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function loadReliabilityFixture() {
  const absolute = resolve(ROOT, RELIABILITY_FIXTURE_PATH);
  if (!existsSync(absolute)) {
    return { available: false, reason: 'fixture-not-found', path: RELIABILITY_FIXTURE_PATH };
  }
  try {
    const parsed = JSON.parse(readFileSyncUtf8(absolute));
    return { available: true, path: RELIABILITY_FIXTURE_PATH, summary: aggregateReliability(parsed) };
  } catch (error) {
    return { available: false, reason: 'fixture-unreadable', path: RELIABILITY_FIXTURE_PATH, error: String(error && error.message ? error.message : error) };
  }
}

function readFileSyncUtf8(path) {
  // eslint-disable-next-line no-sync
  return require('node:fs').readFileSync(path, 'utf8');
}

function renderReliabilitySection(reliability) {
  if (!reliability || !reliability.available || !reliability.summary) {
    return [
      '## Reliability Aggregation',
      '',
      `- unavailable (${reliability && reliability.reason ? reliability.reason : 'not-loaded'})`,
      '',
    ].join('\n');
  }
  const summary = reliability.summary;
  const incomplete = summary.incomplete
    .map((entry) => `${entry.id} (${entry.reasons.join('+')})`)
    .join(', ') || 'none';
  const anchors = [
    `- positive anchors: ${summary.anchors.positive.passed ? 'all passed' : 'VIOLATED'} (${summary.anchors.positive.caseIds.join(', ') || 'none'})`,
    `- negative anchors: ${summary.anchors.negative.passed ? 'all rejected' : 'VIOLATED'} (${summary.anchors.negative.caseIds.join(', ') || 'none'})`,
  ].join('\n');
  return `## Reliability Aggregation (deterministic fixture oracle)

Fixture: ${summary.fixtureId} (${summary.fixtureKind}, deterministic=${summary.deterministic})

| Metric | Value |
| --- | ---: |
| Trials per case (k) | ${summary.k} |
| Raw cases | ${summary.rawCaseCount} |
| Complete cases (denominator) | ${summary.completeCaseCount} |
| Incomplete cases (excluded, retained) | ${summary.incompleteCaseCount} |
| pass^k (all k trials passed) | ${summary.passK} |
| pass@k (at least one trial passed) | ${summary.passAtK} |
| Per-trial success rate | ${summary.perTrialSuccessRate} |
| Flake rate | ${summary.flakeRate} |
| Flake threshold | ${summary.flakeThreshold} |
| Gate | ${summary.gate} |

Gate reasons: ${summary.gateReasons.join('; ')}

${anchors}

- Safety-critical cases: ${summary.safety.caseIds.join(', ') || 'none'} (skip=${summary.safety.skipCount}, flake=${summary.safety.flakeCaseIds.length})
- Flake cases (first failure retained): ${summary.flakeCaseIds.join(', ') || 'none'}
- Incomplete cases: ${incomplete}
- Note: pass^k and pass@k are reported separately and are never interchangeable.
`;
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => (
    `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`
  )).join('\n');
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

${renderReliabilitySection(report.reliability)}
## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- The reliability section above is computed from a deterministic, pre-registered fixture oracle. It is an internal regression signal only: it is not a real provider run, not a human evaluation, and makes no claim about real-model generalization.
`;
}

const start = performance.now();
const [
  scenarioRegistry,
  hostApi,
  e2eFixture,
  schemaText,
  a11yText,
] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  reliability: loadReliabilityFixture(),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# Harness Gap: Deterministic Reliability Aggregation (E01)

## Status

Implemented (internal evaluation only). No product default, product lock, approval semantics, or
user-visible interface/configuration change is introduced by this task.

## Problem

The Agent Dev benefit report counted scenarios, helpers and heuristics but did not expose a
deterministic reliability signal. There was no way to distinguish `pass^k` (all k trials of a case
passed) from `pass@k` (at least one trial passed), no explicit accounting for missing / timeout /
crash / skip cases, no flake detection, and no positive / negative anchor enforcement.

## Scope

Reuse the existing Agent Dev benefit report (`scripts/agent-dev-benefit-eval.mjs`) and the existing
scenario registry (`shared/agent-dev/scenarios.ts`). Do **not** introduce a new metrics platform,
service, dashboard or automation schedule.

Touched files:

- `scripts/lib/reliability-aggregation.mjs` (new, pure aggregation library)
- `scripts/lib/reliability-aggregation.d.mts` (new, type declarations)
- `shared/agent-dev/reliability-fixture.json` (new, pre-registered deterministic oracle)
- `scripts/agent-dev-benefit-eval.mjs` (report integration)
- `harness/specs/rules/reliability-aggregation-boundary.md` (boundary rules)
- `docs/dev/harness-gap-closure/e01-reliability-aggregation.md` (acceptance record)

## Pre-registered design gate (in the fixture)

| Parameter | Value |
| --- | ---: |
| `k` (trials per case) | 3 |
| `minCases` (complete cases) | 20 |
| `flakeThreshold` | 0.1 |

These values live in `shared/agent-dev/reliability-fixture.json` and are pre-registered; they must not
be tuned per run.

## Required behaviour

1. A case is executed `k` times. Trial status is one of `pass`, `fail`, `missing`, `timeout`,
   `crash`, `skip`.
2. Cases with missing / timeout / crash / skip trials (or fewer than `k` recorded trials) are
   `incomplete`: excluded from the pass^k / pass@k / flake denominators but always retained and
   reported in the report.
3. `pass^k` = complete cases where all `k` trials passed / complete cases.
   `pass@k` = complete cases where at least one trial passed / complete cases.
   Both are reported side by side and never used interchangeably.
4. Per-trial success rate = passing trials / recorded trials over complete cases.
5. `flake` = complete cases whose first trial failed and whose later fixed rerun succeeded. The
   first failure is retained; a retried success never washes out the original gate failure, so a
   flaky case never counts towards `pass^k`.
6. Safety-critical cases must have 0 skip and 0 flake.
7. Positive anchors must pass every trial; negative anchors must reject every trial. Any anchor
   violation is `gate=fail`.
8. If complete cases < `minCases`, `gate=insufficient-sample`. A small sample is never reported
   as PASS.
9. The report must contain: raw denominator, pass^k, pass@k, per-trial success rate, flake rate,
   missing/incomplete list, gate and gate reasons.

## Non-goals

- No product default changes, no product lock changes, no approval-semantics changes.
- No scheduled automation.
- No claim about real providers, human evaluation, or real-model generalization.

## Acceptance

See `docs/dev/harness-gap-closure/e01-reliability-aggregation.md`.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Rule: Reliability Aggregation Boundary (E01)

## Scope

Applies to `scripts/lib/reliability-aggregation.mjs`, `scripts/lib/reliability-aggregation.d.mts`,
`shared/agent-dev/reliability-fixture.json` and the reliability section of
`scripts/agent-dev-benefit-eval.mjs`.

## MUST

1. **Deterministic oracle only.** The reliability signal is computed from a pre-registered,
   checked-in fixture with recorded trial outcomes. It must be labelled as a deterministic oracle
   in the output and must never be presented as a real provider run, a human evaluation, or evidence
   of real-model generalization.
2. **Pre-registered design gate.** `k`, `minCases` and the flake threshold are stored in the fixture
   and read from it. They must not be recomputed per run, derived from the observed data, or tuned
   after seeing results.
3. **pass^k and pass@k stay distinct.** `pass^k` counts only cases whose every trial passed;
   `pass@k` counts cases with at least one passing trial. A report must not use one in place of the
   other, and must not label `pass@k` as `pass^k`.
4. **Incomplete cases stay visible.** Cases with missing, timeout, crash or skip outcomes (or with
   fewer than `k` recorded trials) are counted as incomplete, excluded from the pass^k / pass@k /
   flake denominators, and must still be listed in the report with their reasons.
5. **First failure is retained.** A case is flaky when the first trial failed and a later fixed
   rerun succeeded. The retried success must not erase the original failure: the case does not count
   towards `pass^k`, and the first-failure case id is reported.
6. **Anchors are hard gates.** Positive anchor cases must pass every trial and negative anchor cases
   must reject every trial. Any violation yields `gate=fail`.
7. **Safety cases.** Safety-critical cases must show 0 skip and 0 flake, otherwise `gate=fail`.
8. **Small samples are never PASS.** When complete cases are below the registered `minCases`, the
   gate is `insufficient-sample`. The gate value and the reasons must both be reported.
9. **Pure library.** The aggregation module performs no I/O, no network access and no process
   effects; it does not read the clock. It must not mutate caller-owned inputs.

## MUST NOT

1. Must not introduce a new metrics platform, service, dashboard, datastore or scheduled
   automation.
2. Must not change product defaults, product locks, or approval semantics.
3. Must not add user-visible interfaces or configuration for this internal reporting signal.
4. Must not silently drop incomplete cases, or renormalize denominators without reporting the raw
   case count.
5. Must not overwrite a failing first trial with a successful retry.

## Naming

- Gate values: `pass`, `fail`, `insufficient-sample`.
- Trial statuses: `pass`, `fail`, `missing`, `timeout`, `crash`, `skip`.
- Metric keys in the report: `passK`, `passAtK`, `perTrialSuccessRate`, `flakeRate`,
  `rawCaseCount`, `completeCaseCount`, `incompleteCaseCount`, `gate`, `gateReasons`.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 — Deterministic Reliability Aggregation in the Agent Dev Benefit Report

Date: 2025-01-01
Status: Closed (internal evaluation scope)

## Scope

Add a deterministic reliability section to the existing Agent Dev benefit report
(`scripts/agent-dev-benefit-eval.mjs`), reusing the existing scenario registry
(`shared/agent-dev/scenarios.ts`). No new metrics platform, service or automation was created.

## What was added

| Path | Purpose |
| --- | --- |
| `scripts/lib/reliability-aggregation.mjs` | Pure aggregation library (case evaluation, pass^k / pass@k, per-trial rate, flake, anchors, safety, gate). |
| `scripts/lib/reliability-aggregation.d.mts` | Type declarations for the library. |
| `shared/agent-dev/reliability-fixture.json` | Pre-registered deterministic oracle: `k = 3`, `minCases = 20`, `flakeThreshold = 0.1`, anchors, complete and incomplete cases. |
| `scripts/agent-dev-benefit-eval.mjs` | Loads the fixture and renders the reliability section in `report.json` / `report.md`. |
| `harness/specs/tasks/harness-gap-reliability-aggregation.md` | Task spec. |
| `harness/specs/rules/reliability-aggregation-boundary.md` | Boundary rules. |

## Metric definitions (as implemented)

- **Complete case**: exactly `k` trials recorded, all with a comparable outcome (`pass` / `fail`).
- **Incomplete case**: contains `missing`, `timeout`, `crash` or `skip` (or fewer than `k` recorded
  trials). Incomplete cases are excluded from the pass^k / pass@k / flake denominators and are always
  listed in the report with their reasons.
- **pass^k** = complete cases where all `k` trials passed / complete cases.
- **pass@k** = complete cases where at least one trial passed / complete cases.
  The two are reported side by side and never used interchangeably.
- **Per-trial success rate** = passing trials / recorded trials across complete cases.
- **Flake** = complete cases whose first trial failed and whose later fixed rerun succeeded. The first
  failure is retained (the case never counts towards pass^k) and the case id is reported.
- **Anchors**: positive anchor cases must pass every trial; negative anchor cases must reject every
  trial. Any violation is `gate=fail`.
- **Safety**: safety-critical cases require 0 skip and 0 flake, otherwise `gate=fail`.
- **Gate**: `fail` on anchor / safety / flake-threshold violations; otherwise `insufficient-sample`
